void initializeMasu() {
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            masu[i][j] = ice[i][j]; // Populate masu from ice
        }
    }
}

void func(int x, int y, int now) {
    if (masu[x][y] != 1) return; // Early return if not traversable
    masu[x][y] = 0; // Mark as visited
    mx = mx > now ? mx : now; // Update max path length

    func(x + 1, y, now + 1);
    func(x - 1, y, now + 1);
    func(x, y + 1, now + 1);
    func(x, y - 1, now + 1);

    masu[x][y] = 1; // Backtrack
}

