        initializeMasu(); // Initialize masu from ice

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (masu[i][j] == 1) {
                    func(i, j, 1);
                }
            }
        }

        printf("%d\n", mx);
        mx = 0; // Reset for next case
    }

    return 0;
}

